import 'vue'

/* ==========================================================================
   全局属性类型补充
   main.ts 里挂了 $perm 辅助函数，供模板里做「按权限禁用」这类判断
   （v-perm 指令是「移除元素」，而开关/按钮有时需要保留但置灰）。
   ========================================================================== */

declare module 'vue' {
  interface ComponentCustomProperties {
    /** 当前登录人是否拥有该权限码 */
    $perm: (code?: string) => boolean
  }
}

export {}
